import{_ as e,c as t,o as r,ak as s}from"./chunks/framework.gmyagHYt.js";const _=JSON.parse('{"title":"必要准备","description":"安装之前的准备工作","frontmatter":{"title":"必要准备","description":"安装之前的准备工作","layout":"doc"},"headers":[],"relativePath":"version/v3/docs/base/paper.md","filePath":"version/v3/docs/base/paper.md"}'),l={name:"version/v3/docs/base/paper.md"};function c(n,a,o,i,d,p){return r(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="_1-下载并安装-net10" tabindex="-1">1. 下载并安装.NET10 <a class="header-anchor" href="#_1-下载并安装-net10" aria-label="Permalink to “1. 下载并安装.NET10”">​</a></h1><h2 id="_1-1-下载-net10" tabindex="-1">1.1 下载.NET10 <a class="header-anchor" href="#_1-1-下载-net10" aria-label="Permalink to “1.1 下载.NET10”">​</a></h2><p>访问<a href="https://builds.dotnet.microsoft.com/dotnet/WindowsDesktop/10.0.9/windowsdesktop-runtime-10.0.9-win-x64.exe" target="_blank" rel="noreferrer">微软官方地址</a>进行下载</p><h2 id="_1-2-安装-net10" tabindex="-1">1.2 安装.NET10 <a class="header-anchor" href="#_1-2-安装-net10" aria-label="Permalink to “1.2 安装.NET10”">​</a></h2><p>双击下载下来的文件，点击<code>安装</code>。<br><img src="https://tuchuang.ets2la.cn/csharp/NET10install.png" alt="" loading="lazy"> 如果你双击打开.NET10的安装程序是这样的，这表明你已经有了基础的环境，直接点击 <code>关闭</code>即可。 <img src="https://tuchuang.ets2la.cn/csharp/NET10install2.png" alt="" loading="lazy"></p><div class="tip custom-block"><p class="custom-block-title">提醒</p><p>虽然软件在未安装.NET10的情况下会询问是否自动下载但可能受网络影响下载速度慢，所以手动安装.NET10仍然是最稳妥的方式。</p></div><h1 id="_2-获取软件安装包" tabindex="-1">2. 获取软件安装包 <a class="header-anchor" href="#_2-获取软件安装包" aria-label="Permalink to “2. 获取软件安装包”">​</a></h1><h2 id="_2-1-平台" tabindex="-1">2.1 平台 <a class="header-anchor" href="#_2-1-平台" aria-label="Permalink to “2.1 平台”">​</a></h2><ul><li>GitHub 访问<a href="https://github.com/ETS2LA/ETS2LA/releases" target="_blank" rel="noreferrer">官方仓库</a> ，在 <code>Assets</code> 中选择名为<code>ETS2LA-win-release.msi</code> 的文件进行下载。 <img src="https://tuchuang.ets2la.cn/csharp/20260902101942292.png" alt="" loading="lazy"></li><li>CNB 考虑到国内网络情况，ETS2LA中国官方在<a href="https://cnb.cool/" target="_blank" rel="noreferrer">CNB</a>上对官方GitHub仓库进行了镜像上传，访问<a href="https://cnb.cool/ETS2LA-CN/Euro-Truck-Simulator-2-Lane-Assist/-/releases" target="_blank" rel="noreferrer">CNB仓库</a> 在 <code>附件</code> 中选择名为<code>ETS2LA-win-release.msi</code> 的文件进行下载。 <img src="https://tuchuang.ets2la.cn/csharp/20260902102012732.png" alt="" loading="lazy"></li></ul><h2 id="_2-2-下载" tabindex="-1">2.2 下载 <a class="header-anchor" href="#_2-2-下载" aria-label="Permalink to “2.2 下载”">​</a></h2><p>使用浏览器直接下载可能会遇到如图所示的情况 <img src="https://tuchuang.ets2la.cn/csharp/20260902102456028.png" alt="" loading="lazy">， 需点击 <code>...</code> 并选择保留，会弹出如图所示的信息 <img src="https://tuchuang.ets2la.cn/csharp/20260902102641923.png" alt="" loading="lazy">， 点击 <code>删除</code> 旁边的下拉按钮并选择 <code>仍然保留</code> 即可正常下载。 <img src="https://tuchuang.ets2la.cn/csharp/20260902102844097.png" alt="" loading="lazy"></p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>下载平台的选择关系到软件在使用过程中从远端获取插件的地址，国内无条件用户请慎重选择从GitHub上下载安装包</p><p>ETS2LA国内官方不售卖任何远程安装服务</p></div><p>至此准备工作全部完成，可点击下面的 安装 按钮进入到安装教程</p>',13)])])}const g=e(l,[["render",c]]);export{_ as __pageData,g as default};
